mapper.select:
SELECT r.*, COALESCE(u.nickname, u.username) AS reporter_name, CASE WHEN r.target_type = 'post' THEN p.title WHEN r.target_type = 'comment' THEN CONCAT('评论：', LEFT(c.content, 30)) END AS target_title FROM report r LEFT JOIN `user` u ON u.id = r.user_id LEFT JOIN post p ON r.target_type = 'post' AND p.id = r.target_id LEFT JOIN comment c ON r.target_type = 'comment' AND c.id = r.target_id
AND r.status = #{status}
ORDER BY r.status ASC, r.id DESC
